{
  "title": "真实模型链路验收",
  "summary": "三大陆修士逐道求存，叩探界门隐秘。",
  "unresolvedQuestions": [
    {
      "id": "uq_01",
      "question": "界门背后是否连通域外天魔族群？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "uq_02",
      "question": "寿元燃尽后是否存在真灵转生之法？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_03",
      "question": "三大陆界门开启时是否会触发天地灵气守恒律的反向大吞噬？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_04",
      "question": "大乾天朝皇室命修是否秘密掌握借国运转移燃寿反噬之法？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_05",
      "question": "补天阁阁主本尊是否早已突破破虚境迈入主宰境？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "uq_06",
      "question": "未来高阶成长仍须遵守灵泉仅增未来寿储、不治疗道伤或返还已付晋阶/燃寿成本的规则；实际可得来源与疗程尚需逐层设计。",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_07",
      "question": "虚空神晶若被大量采集，是否会导致苍冥大陆虚空裂隙提前扩大并崩塌？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_08",
      "question": "太古界门破虚匙共有几柄，补天阁内部是否封存有另外的钥匙残片？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_09",
      "question": "十年前青玄极天界门的无故灵震是否由主角家族或某位通天境强者的秘密燃寿破门引发？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_10",
      "question": "影杀阁乾都刺杀案幕后真凶是否为大乾内部企图夺嫡并推翻宗门妥协路线的皇子？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "audit-power-opening",
      "question": "旧正文开篇燃寿越阶问题仍未改写；当前1–32章替换提案不发动真解，33–100宏观也不发动。须在新章纲、正文及事件一致后复核；不得把旧燃寿额与新提案下界混账。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-resource-definitions",
      "question": "已补充绝命死息 res_15、诸天通宝 res_16 的资源提案并修正势力引用；新增品阶、材质、发行与保存规则尚需对照正文核验，不能视为已确立事实。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-travel-rules",
      "question": "新宏观采用北航五日、返航六日、14,000枚专项款及有时限的外港担保，尚待逐章落地。旧稿打点、火晶换舱和第55章信物均不作为新版实际支付或准入依据；历史保留待对照。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-tier-exceptions",
      "question": "旧稿越阶施术与神器使用仍待替换正文修复。新版百章玄府、赵仍玄府，不采用破虚杀主宰或通天禁术反噬的旧结局；原世界各阶门槛与成本完全保留，后续450章高阶成长仍需有来源。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-resource-usage",
      "question": "资源使用规则为新提案，必须内容复核并重算各章收入/支出。灵泉终生上限30年不能支撑旧第28章神海突破及早期燃寿；历史正文未改，不得倒填已经饮用或凭未来库存先花寿元。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-first-volume-foundation",
      "question": "当前世界的分区、寿储诊断与凝元三重规则仍为提案；已有1–32章替换章纲和33–100宏观，但需分项内容复核与逐章生成，不视新诊断、修炼、药程为已采纳事实。",
      "blocking": true,
      "status": "open"
    }
  ]
}

{
  "coreConflict": "先天短寿的林辰由矿务逃生追查跨陆扣工与非法货运，在寿储、境界与各方利益限制下同伙伴救人、查清父亲守门及外山掩案责任。百章只切断已实证的一条三地运输链；九鼎全貌、三残片与最终界门危机仍是约450章全书必须收束的主线。",
  "endingDirection": "百章有救人、断运、部分父案澄清和玄府成长的可核结局。1–100是450章的阶段验收；接下来的有限寿源、高阶反派、钥匙余片与九鼎机制必须另建经审查的来源和行动链，不将450章全书结局撤销。 没有返寿、燃寿白发、道伤凭空痊愈或三大陆永久太平。此卷不清算全部九鼎，公开传播仍限实到地点。",
  "unresolvedQuestions": [
    {
      "id": "uq_03",
      "question": "【既有记录，非后卷事实依据】三大陆界门开启时是否会触发天地灵气守恒律的反向大吞噬？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_04",
      "question": "【既有记录，非后卷事实依据】大乾天朝皇室命修是否秘密掌握借国运转移燃寿反噬之法？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_06",
      "question": "【既有记录，非后卷事实依据】主角以命寿换力突破至归一境时，延寿灵泉能否中和其肉身永久衰老的暗伤？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_08",
      "question": "【既有记录，非后卷事实依据】太古界门破虚匙共有几柄，补天阁内部是否封存有另外的钥匙残片？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_09",
      "question": "【既有记录，非后卷事实依据】十年前青玄极天界门的无故灵震是否由主角家族或某位通天境强者的秘密燃寿破门引发？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "audit-scene-31",
      "question": "【既有记录，非后卷事实依据】第31章已绑定无尽虚海商路 loc_21；跨大陆海域不挂在青玄大陆之下。航程天数仍随时间线统一核查。",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "audit-volume-timeline",
      "question": "当前三卷32/66/100边界不变，新宏观第436日高潮、第466日三十日回访。旧稿第50/80日终局与十载血战不作为新时间线。新日历仍须逐章实现并验证。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-artifact-continuity",
      "question": "新百章只持第一片，第二片经程抵押赵府，第三片未取得；不再安排73章合匙、88章宝鉴或98章锁销。旧稿对应越阶使用尚未替换，新的持物和角色认知须分开复核。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-ending-cost",
      "question": "新宏观采用第19日诊察下界7、120日扣3、199/209日各加5、415日扣10并扣自然流逝；466日约2.775342仅为健康条件成立时的提案预算。旧稿不足两年/三年数字保留历史，不混入新账。须通过实际新章节与复诊才能认定余额。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-relationship-stages",
      "question": "本轮撤回旧投影、苏被囚与夜南征的未来关系，改为苏留宗独立调查、夜外港有限合作、贺有账航款、陆自认改签。宏观阶段已同步，尚须在逐章行动中验证，不改已采纳事件。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-knowledge-reveal-order",
      "question": "新提案撤回宝鉴推演与完整父辈留影，按44/53/66/72/85/95章实际材料递进；第二片318日入赵府只属设计真相，林仍须证据确认。旧稿已采纳认知另待逐章替换，禁止倒填。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-opening-growth",
      "question": "第1–32章成长提案仍须对照各章动作、伤情与晋阶前置复核；33–50已补，前50章已齐但整体质量尚待复核。旧稿高阶成就不能充作新方案前置。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-opening-quality",
      "question": "前50章现有提案；33–35局部叙事复审通过不代表前50章整体、文学正文或全书通过。仍需分批和整体质量验收。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-resource-growth-budget",
      "question": "新章纲逐项核对寿储、药程、航款和物品；第51–100章尚未完整逐章落地，不据宏观预算认定已经获得或花费。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-first-volume-blueprint",
      "question": "第一卷32章已提案化，值守交接本轮修到188日午正与首夜；第一卷与后卷连续性及旧正文差异仍待整体复核。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-v1-outline-review",
      "question": "第1–32章章纲尚需在当前人物、认知、资源与值守方案下完成整体复核；本轮局部报告不替代第一卷验收。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-v23-macro",
      "question": "后两卷宏观待整体核验；33–50已有章纲，51–100未完整逐章展开。六号箱核证和仓火已补36–39章纲，36–39局部复审已通过，正文实现仍待验证，旧正文差异未修复。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-guard-return-chain",
      "question": "世界19/圣经31/计划30的值守专项已在正确的提案评审阶段通过；当前轮班没有修改。该结论不是正文已实现或整体设计通过，仍须按实际章节核对交接、休息、伤情和返宗。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-first-warehouse-fire",
      "question": "第37章首仓火已有退包装、普通灯架倾倒、油火纸绳燃迹与外桌携页者的现场链；谁使灯倒、是否事故及携页者身份仍未确认，须后续查证。不得与47–53章另一场程纵火自动并案；若最终无法核实，明确未查明及证据边界，不称已破火案。 世界19/圣经33/计划33的36–39局部复审已通过，支持所列触发与现场分工；具体倾灯责任仍未查明，该通过不替代火案或全书验收。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-barge-inspection",
      "question": "43–46完整材料评审因片段ID失败，压缩来源最终局部通过但不能替代全部场景及关系复核。47–50已接停牌、核证、陆到案和火场前置；51–53仍须实际救吴卢、交改签页和安排伤后安置，不提前闭合五人救援或整体质量。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-second-warehouse-fire",
      "question": "50章第二次仓火点火和第二片封匣仅读者视角，林未在点火桌边；须通过火后证人与物证再查明，不能推断37首仓火同凶。51章从254同一门口接续救吴卢与陆，不可瞬间康复或拿到第二片原物；261–270食宿与七日轻役待落实。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-first50-narrative",
      "question": "13–17已于38版重构并完成含前后完整场景的局部复审；本版重构40–43的经营、互信、工人自主离院和潮路行动，仍须完成本组及全50章跨章验收。47–50限制解释精简、全局知情复核仍待处理；50/50不放行正文。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-message-arrivals",
      "question": "rel_02和林苏来信均按实际获知章节分开；rel_06撤回36密券旧来源和33章提前生效的268回令。258寄报告、262抵乾都、268回令到程，51–66章纲未齐须按真正到达章继续拆；局部修复不等于全局知情通过。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-review-capacity",
      "question": "应用整体内容评审的力量、人物、故事材料超过240000字符单次容量，尚未完成四领域验收。需实现覆盖原文的分阶段评审与跨阶段综合复核，不得截断材料或以外部专项报告冒充应用审核通过。",
      "blocking": true,
      "status": "open"
    }
  ]
}

{
  "targetChapterCount": 100,
  "volumeCount": 3,
  "mainConflict": "先天短寿的林辰由矿务逃生追查跨陆扣工与非法货运，在寿储、境界与各方利益限制下同伙伴救人、查清父亲守门及外山掩案责任。百章只切断已实证的一条三地运输链；九鼎全貌、三残片与最终界门危机仍是约450章全书必须收束的主线。",
  "theme": "活命与查真相不能以牺牲无辜者代价换取；信任来自共同选择和承担自己一方的责任。",
  "protagonistArc": "从负伤矿工到能接受伙伴自主选择的凝元修士，再经数月修习、实测丹府与支付十元载成为玄府初期；力量增加时可用寿储反而减少。百章不发动逆命真解，不越阶斩高境，不把神兵持有当作启动权限。",
  "endingDirection": "百章有救人、断运、部分父案澄清和玄府成长的可核结局。1–100是450章的阶段验收；接下来的有限寿源、高阶反派、钥匙余片与九鼎机制必须另建经审查的来源和行动链，不将450章全书结局撤销。 没有返寿、燃寿白发、道伤凭空痊愈或三大陆永久太平。此卷不清算全部九鼎，公开传播仍限实到地点。",
  "keyTurns": [
    "第10–12章：伤重林辰与曾撤供的梁九分工救人，只改变普通输送位置；苏保留封样及己方不利证词，争得有限复核，众人仍负伤、欠债和受限。",
    "第23–29章：主角为救人暴露自己，创造顾峤同阶制敌的窗口，取得并分配有限泉液；完成两次十日疗程后南行，苏选择留宗。卷末凝元三重，不能沿用神海及二十年燃寿。",
    "第44/50–51章：潮沟截驳与同阶仓战，林救人放过程，陆承认自身改签，贺付出船损。",
    "第61–66章：付费北航后在受限外港救出七名矿工，夜真身守撤离路，林放弃第二片，不入界渊。",
    "第83章：数月努力与诊察后，实际付十元载晋玄府；不能再用旧法器承载元罡。",
    "第88–100章：同阶截押运救工友、部分父案澄清、三十日回访；约450章全书的高阶成长与界门总收束仍待后续逐层完成。"
  ],
  "openQuestions": [
    {
      "id": "oq_01",
      "question": "【旧稿对照与新提案审核未完成】第一卷32章章纲已替换；后两卷改为港口救人与玄府成长，原归一/破虚及百章杀主宰路线撤回。仍须审查新宏观、分批补齐后续章纲并核对历史差异，正文不放行。",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "oq_02",
      "question": "【旧稿对照与新提案审核未完成】第一卷32章章纲已替换；后两卷改为港口救人与玄府成长，原归一/破虚及百章杀主宰路线撤回。仍须审查新宏观、分批补齐后续章纲并核对历史差异，正文不放行。",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "oq_03",
      "question": "【旧稿对照与新提案审核未完成】第一卷32章章纲已替换；后两卷改为港口救人与玄府成长，原归一/破虚及百章杀主宰路线撤回。仍须审查新宏观、分批补齐后续章纲并核对历史差异，正文不放行。",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "baseline-content-review",
      "question": "现有前50章替换提案，批准旧版仍10。整体设计质量、各章正文与历史事件一致性尚未验收，局部章纲复审不能放行正式写作。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "opening-growth-repair",
      "question": "第1–32章成长提案仍须对照各章动作、伤情与晋阶前置复核；33–50已补，前50章已齐但整体质量尚待复核。旧稿高阶成就不能充作新方案前置。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "opening-quality-review",
      "question": "前50章现有提案；33–35局部叙事复审通过不代表前50章整体、文学正文或全书通过。仍需分批和整体质量验收。",
      "blocking": true,
      "status": "open"
    },
